  tool_density_ref_a_label: 'NIST SP 811 — Guide for the Use of the International System of Units (Leitfaden zum SI)',
  tool_density_ref_b_label: 'Engineering ToolBox — Densities of common solids (Dichten gängiger Feststoffe)',
  tool_density_references: 'NIST SP 811 — Leitfaden zur Verwendung des SI; Engineering ToolBox — Dichten fester Stoffe.',
  tool_density_result_note: 'Die Einheiten werden automatisch umgerechnet; Ergebnisse sind auf 5–6 signifikante Stellen gerundet.',
  tool_density_result_tag: 'Ergebnis',
  tool_density_sample: 'Beispiel laden',
  tool_density_sg_tpl: 'Relative Dichte bzw. spezifisches Gewicht (Wasser = 1): {sg}',
  tool_density_sink: 'geht in Süßwasser unter',
  tool_density_solve_density: 'Dichte (aus Masse und Volumen)',
