  tool_sync_song_lyrics_to_lrc_by_tapping_lyrics_placeholder: 'Erste Liedzeile\nZweite Liedzeile',
  tool_sync_song_lyrics_to_lrc_by_tapping_offset: 'Globaler Versatz (ms)',
  tool_sync_song_lyrics_to_lrc_by_tapping_offset_hint: 'Positive Werte verzögern alle exportierten Zeilen.',
