  tool_tip_work_round_total_tpl: 'Summe von {a} auf {b} aufgerundet, das Trinkgeld beträgt damit {tip} ({p})',
  tool_tip_work_split_tpl: 'Pro Person = {total} ÷ {n} {eq} {v}',
  tool_tip_work_tip_amt_tpl: 'Trinkgeldsatz = {tip} ÷ {base} = {p}',
